// Hidden Track: Fresh Cuts data for /, /listen and /embed.
// Add new tracks to the TOP of the `tracks` array (newest first).
import type { Mood } from "@/lib/moods";

// tags: moods for filters, the map and playlists. Pick from
// hard, halloween, cinematic, party, chill, love, sad, funny (see src/lib/moods.ts).
// Anything spooky, haunted, horror or October-night gets "halloween" so it lands on /halloween.
export type Track = { title: string; lane: string; hook: string; href: string; tags?: Mood[] };

export const songId = (href: string) => href.split("/song/")[1] ?? "";
// The Suno MP4 plays reliably; the CloudFront .m4a is kept only as a last resort.
export const primarySrc = (id: string) => `https://cdn1.suno.ai/${id}.mp4`;
export const fallbackSrc = (id: string) => `https://d2lwuy8qc234o3.cloudfront.net/1/clip/${id}.m4a`;

export const slugify = (title: string) =>
  title.toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g, "").replace(/&/g, " and ").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "track";

export const fmt = (s: number) => {
  if (!Number.isFinite(s) || s < 0) return "0:00";
  const m = Math.floor(s / 60);
  return `${m}:${String(Math.floor(s % 60)).padStart(2, "0")}`;
};

