// Stable per-track share slugs (/?t=<slug>). Later duplicates get -2, -3...
export const slugs: string[] = (() => {
  const seen = new Map<string, number>();
  return tracks.map((t) => {
    const base = slugify(t.title);
    const n = (seen.get(base) ?? 0) + 1;
    seen.set(base, n);
    return n === 1 ? base : `${base}-${n}`;
  });
})();

export const indexForSlug = (slug: string | null | undefined) => {
  if (!slug) return -1;
  return slugs.indexOf(slug.toLowerCase());
};
